import{_ as t,o as a,c as d,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const n=JSON.parse('{"title":"复盘：这张源码地图你现在走完了","description":"","frontmatter":{"title":"复盘：这张源码地图你现在走完了"},"headers":[],"relativePath":"dayjs-walkthrough-course/09-review.md","filePath":"dayjs-walkthrough-course/docs/09-review.md"}'),o={name:"dayjs-walkthrough-course/09-review.md"};function l(s,e,c,i,m,u){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="复盘-这张源码地图你现在走完了" tabindex="-1">复盘：这张源码地图你现在走完了 <a class="header-anchor" href="#复盘-这张源码地图你现在走完了" aria-label="Permalink to &quot;复盘：这张源码地图你现在走完了&quot;">​</a></h1><p>八章之前，你只是 dayjs 的使用者：会调 API、偶尔翻文档。现在你能定位它每个行为的实现行号、能解释每个「怪现象」的机制、能在 node 里亲手复现——把会的东西清点一遍，确认每一项都真的在你手里。</p><h2 id="能力对账表" tabindex="-1">能力对账表 <a class="header-anchor" href="#能力对账表" aria-label="Permalink to &quot;能力对账表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来自</th><th>你现在能独立做的事</th></tr></thead><tbody><tr><td>第 1 章</td><td>画出工厂函数的四行逻辑，解释克隆防御与 <code>$isDayjsObject</code> 双保险</td></tr><tr><td>第 2 章</td><td>对任意输入说出 parseDate 走哪条分支，解释 null 为何显式判无效</td></tr><tr><td>第 3 章</td><td>列出实例的九个字段，解释预计算缓存与 <code>$</code> 私有约定</td></tr><tr><td>第 4 章</td><td>沿 set/add 两条路径指出克隆发生在哪一行，预测月末溢出的结果</td></tr><tr><td>第 5 章</td><td>用两个工厂解释 startOf 如何吃下八个单位，推算不同 weekStart 下的周对齐</td></tr><tr><td>第 6 章</td><td>手推 format 的一次 replace：字面量逃逸、查表、default 兜底的优先级</td></tr><tr><td>第 7 章</td><td>画出 L/Ls 注册表与 parseLocale 的回退链，区分全局与实例切换</td></tr><tr><td>第 8 章</td><td>背出插件协议三参数与 <code>$i</code> 幂等，读懂一个官方插件的完整源码</td></tr></tbody></table><p>每一行的验证物都在伴生仓：<code>cd companion &amp;&amp; npm test</code>，8 组共 53 条探针在锁定 ref（<code>iamkun/dayjs@0f6c19e</code>）的源码上跑，应当全绿。哪一行心虚，回那一章的「验证」小节重做一次。</p><h2 id="八问自查" tabindex="-1">八问自查 <a class="header-anchor" href="#八问自查" aria-label="Permalink to &quot;八问自查&quot;">​</a></h2><ul><li>问题一（动手）：<code>dayjs(&#39;2026-01-31&#39;).add(1, &#39;month&#39;).format(&#39;YYYY-MM-DD&#39;)</code> 是什么？为什么？</li></ul><details><summary>看答案</summary><p><code>2026-02-28</code>。add 月复用 set 月，先落 1 号、改完月、再夹回月末（回查第 4 章 $set 的月分支）。</p></details><ul><li>问题二：<code>dayjs(null)</code> 与 <code>dayjs(undefined)</code> 结果差在哪？</li></ul><details><summary>看答案</summary><p>null 是 Invalid Date，undefined 是现在——parseDate 的前两条分支刻意分开（回查第 2 章）。</p></details><ul><li>问题三（预测）：en 环境下 <code>dayjs(&#39;2026-08-30&#39;).startOf(&#39;week&#39;)</code> 与 zh-cn 环境下差几天？</li></ul><details><summary>看答案</summary><p>差 6 天：en 周日起算得 08-30 当天，zh-cn 周一起算得 08-24（回查第 5 章 C.W 分支）。</p></details><ul><li>问题四：<code>format(&#39;[YYYY]&#39;)</code> 为什么输出字面量 YYYY？</li></ul><details><summary>看答案</summary><p>正则的方括号分支捕获内容、回调里 <code>$1</code> 优先返回（回查第 6 章三级短路）。</p></details><ul><li>问题五：实例上调用 <code>month()</code> 不传参和传参，返回类型分别是什么？</li></ul><details><summary>看答案</summary><p>数字与新实例——getter 注册表经 <code>$g</code> 分派，无参读 <code>$M</code> 缓存、有参转 set（回查第 3 章）。</p></details><ul><li>问题六（动笔）：写出「dayjs(&#39;2026-08-28T18:00&#39;).format(&#39;A&#39;)」的输出并说明 meridiem 的兜底逻辑。</li></ul><details><summary>看答案</summary><p><code>PM</code>。语言包没提供 meridiem 时用内置 <code>hour &lt; 12 ? &#39;AM&#39; : &#39;PM&#39;</code>（回查第 6 章）。</p></details><ul><li>问题七：已加载 zh-cn、未加载 zh 时 <code>locale(&#39;zh-TW&#39;)</code> 得到什么？</li></ul><details><summary>看答案</summary><p>取决于全局 L 与 zh 的注册状态：zh-TW 降级试 zh，若 zh 已注册则用 zh；若未注册则 l 为空、回落到全局默认 L——不是「保持实例原语言」。递归调用丢了 isLocal，这是实例切换唯一能影响全局的缝隙（回查第 7 章解析链细节，用探针跑一遍三种组合）。</p></details><ul><li>问题八（预测）：插件里 <code>c.prototype.x = ...</code> 与 <code>dayjs.x = ...</code> 分别给谁用？</li></ul><details><summary>看答案</summary><p>前者挂到全部实例（d().x()），后者只是工厂上的静态方法（dayjs.x()，实例调不到）（回查第 8 章）。</p></details><h2 id="这门课的边界" tabindex="-1">这门课的边界 <a class="header-anchor" href="#这门课的边界" aria-label="Permalink to &quot;这门课的边界&quot;">​</a></h2><p>本课程引用的全部源码出自锁定提交 <code>iamkun/dayjs@0f6c19e</code>，遵循 MIT 许可（Copyright (c) 2018-present, iamkun）；引用均为逐字摘录并标注出处，课程本身是独立的教学解读，与官方文档无关。上游仓库仍在演进，新版本的实现可能与本课引用行不同——以你 checkout 的版本为准，走读方法（跟着探针读、先猜后跑、找基本概念）比任何具体行号更长寿。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>对任何一个新机制，你的走读套路已经成型：先跑探针看行为，再打开源码对行号，最后用「为什么这么设计」收尾。<a href="./source-map.html">源码地图速查</a>给了你继续往下走的入口：utc、timezone、relativeTime 三大官方插件是天然的第二圈路线，每个都不过一两百行，而你已经握着读它们的全部钥匙。术语随时回<a href="./glossary.html">术语表</a>。</p>',26)])])}const p=t(o,[["render",l]]);export{n as __pageData,p as default};
